			// From earlier: company "github.com/company/" separated pkg and pkg/sub into company group, but company root "github.com/company" stayed general? Let's see:
			// company "github.com/company" with imports company/pkg, company/pkg/sub, company, company2/pkg:
			// Without slash: all company imports (including company root) were in same group (company group?) Actually without slash, all were in company group: company, company/pkg, company/pkg/sub, company2/pkg all same group (company)
			// With slash: company/pkg, company/pkg/sub were company, company root and company2 were general? Let's recall:
			// Earlier test:
			// company "github.com/company" with imports company/pkg, company/pkg/sub, company, company2/pkg:
			// output: all in same group (company)
			// company "github.com/company/" with same imports:
			// output: company and company2 were general, company/pkg and pkg/sub were company.
			// So trailing slash for company means only subpackages of company/ are company, not company itself nor company2.
			// So for company, trailing slash logic is: path starts with companyPrefix (including slash) => company. So "github.com/company" does NOT start with "github.com/company/" (missing slash), so not company. "github.com/company/pkg" DOES start with "github.com/company/", so company. That matches observed.
			// So for company with trailing slash, implement prefix match as path has prefix cp.
			if strings.HasPrefix(path, cp) {
				return true
			}
		} else {
			// Without slash: path == cp OR path starts with cp+"/" OR path starts with cp and next char is "/"? Actually company without slash matched company2? Let's see:
			// company "github.com/company" matched company2/pkg as company in earlier test? We had:
			// imports: company/pkg, company/pkg/sub, company2/pkg
			// company "github.com/company" without slash: all three were in company group? Actually earlier output:
			// company without slash:
			// all company imports (including company2/pkg?) Wait company2/pkg is "github.com/company2/pkg" which starts with "github.com/company"? No, "github.com/company2" starts with "github.com/company"? Let's check: "github.com/company2/pkg" has prefix "github.com/company" ? String prefix: "github.com/company" is prefix of "github.com/company2/pkg"? Yes, because "github.com/company" + "2/pkg" => prefix matches "github.com/company". So without slash, company2 would be considered company (since prefix match without requiring slash). That matches earlier observation where company without slash grouped company2/pkg as company.
			// So for company without slash, matching is simple prefix: path starts with cp.
			// For company with slash, matching is prefix with slash included (so company2 not match).
			if path == cp || strings.HasPrefix(path, cp+"/") || strings.HasPrefix(path, cp) {
				// For without slash, we want prefix match even without slash boundary? That would match company2 as company.
				// Original behavior for company without slash did match company2/pkg as company? Let's see earlier test:
				// company "github.com/company" with imports company/pkg, company/pkg/sub, company2/pkg:
				// output: all in same group (company) - yes, company2 was company.
				// So implement prefix match: strings.HasPrefix(path, cp)
				if strings.HasPrefix(path, cp) {
					return true
				}
			}
		}
	}
	return false
}

func main() {
	// flag parsing
	var (
		applyToGenerated   bool
		companyPrefixesStr string
		excludesStr        string
		filePath           string
		formatFlag         bool
		importsOrderStr    string
		listDiff           bool
		localStr           string
		outputStr          string
		projectName        string
		recursive          bool
		rmUnused           bool
		separateNamed      bool
		setAlias           bool
		setExitStatus      bool
		useCache           bool
		showVersion        bool
		showVersionOnly    bool
	)
	flag.BoolVar(&applyToGenerated, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&companyPrefixesStr, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&excludesStr, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&filePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&formatFlag, "format", false, "Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&importsOrderStr, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	flag.BoolVar(&listDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&localStr, "local", "", "Deprecated")
	flag.StringVar(&outputStr, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&projectName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&rmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	flag.BoolVar(&separateNamed, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&setAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&setExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&useCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&showVersion, "version", false, "Show version information")
	flag.BoolVar(&showVersionOnly, "version-only", false, "Show only the version string")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		flag.PrintDefaults()
	}

	flag.Parse()

	if showVersion {
		fmt.Printf("version: %s\n", versionStr)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", versionStr)
		fmt.Printf("commit: n/a\n")
		fmt.Printf("source: github.com/incu6us/goimports-reviser/v3\n")
		return
	}
	if showVersionOnly {
		fmt.Println(versionStr)
		return
	}

	// validate imports-order
	orderGroups := []string{"std", "general", "company", "project"}
	if importsOrderStr != "" {
		orderGroups = []string{}
		for _, part := range strings.Split(importsOrderStr, ",") {
			t := strings.TrimSpace(part)
			if t == "" {
				continue
			}
			orderGroups = append(orderGroups, t)
		}
		if len(orderGroups) < 4 {
			flag.Usage()
			log.Fatalf("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
		}
		allowed := map[string]bool{"std": true, "general": true, "company": true, "project": true, "blanked": true, "dotted": true}
		for _, g := range orderGroups {
			if !allowed[g] {
				flag.Usage()
				log.Fatalf("unknown order group type: \"%s\"", g)
			}
		}
	}

	args := flag.Args()
	var paths []string
	if filePath != "" {
		paths = append(paths, filePath)
	}
	paths = append(paths, args...)

	if len(paths) == 0 {
		flag.Usage()
		log.Println("no file(s) or directory(ies) specified on input")
		return
	}

	log.Printf("Paths: %v\n", paths)

	// company prefixes
	var companyPrefixes []string
	if companyPrefixesStr != "" {
		for _, cp := range strings.Split(companyPrefixesStr, ",") {
			cp = strings.TrimSpace(cp)
			if cp != "" {
				companyPrefixes = append(companyPrefixes, cp)
			}
		}
	}

	// excludes
	var excludePatterns []string
	if excludesStr != "" {
		for _, ep := range strings.Split(excludesStr, ",") {
			ep = strings.TrimSpace(ep)
			if ep != "" {
				excludePatterns = append(excludePatterns, ep)
			}
		}
	}

	isExcluded := func(absPath string) bool {
		cwd, _ := os.Getwd()
		rel, err := filepath.Rel(cwd, absPath)
		if err != nil {
			rel = absPath
		}
		// normalize to forward slashes for matching? filepath.Match uses OS separator, but we keep as is.
		for _, pat := range excludePatterns {
			if strings.HasSuffix(pat, "/") {
				// directory prefix: check rel starts with pat or abs contains pat
				if strings.HasPrefix(rel, pat) || strings.HasPrefix(absPath, pat) || strings.Contains(rel, pat) || strings.Contains(absPath, pat) {
					return true
				}
				trimmed := strings.TrimSuffix(pat, "/")
				if strings.HasPrefix(rel, trimmed+"/") || rel == trimmed {
					return true
				}
				if strings.HasPrefix(absPath, trimmed+"/") || strings.Contains(absPath, "/"+trimmed+"/") || strings.HasSuffix(absPath, "/"+trimmed) {
					// additional check
					if strings.Contains(absPath, trimmed) {
						// For ".git/" we want to match any path containing ".git/"
						if strings.Contains(absPath, pat) {
							return true
						}
					}
				}
				continue
			}
			// try match rel
			if ok, _ := filepath.Match(pat, rel); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, absPath); ok {
				return true
			}
			// Also try match with forward slashes
			if ok, _ := filepath.Match(pat, filepath.ToSlash(rel)); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, filepath.ToSlash(absPath)); ok {
				return true
			}
		}
		return false
	}

	// Determine output mode
	outputMode := outputStr
	if outputMode != "file" && outputMode != "stdout" && outputMode != "write" {
		outputMode = "file"
	}

	type fileTask struct {
		absPath           string
		relArg            string // original arg for logging? Actually we log per arg, not per file
		isDotDot          bool   // from ... expansion
		origContent       []byte
		formattedContent  []byte
		changed           bool
		skip              bool
		isGenerated       bool
		errorOccurred     bool
	}

	var tasks []fileTask

	// collect files
	for _, p := range paths {
		log.Printf("Processing %s\n", p)
		if strings.Contains(p, "...") {
			base := strings.Split(p, "...")[0]
			base = strings.TrimSpace(base)
			if base == "" {
				base = "."
			}
			base = strings.TrimSuffix(base, "/")
			if base == "" {
				base = "."
			}
			var baseAbs string
			if filepath.IsAbs(base) {
				baseAbs = base
			} else {
				cwd, _ := os.Getwd()
				baseAbs = filepath.Join(cwd, base)
			}
			filepath.WalkDir(baseAbs, func(wp string, d fs.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if d.IsDir() {
					if isExcluded(wp) {
						return filepath.SkipDir
					}
					return nil
				}
				if !strings.HasSuffix(wp, ".go") {
					return nil
				}
				if isExcluded(wp) {
					return nil
				}
				content, err := os.ReadFile(wp)
				if err != nil {
					return nil
				}
				isGen := isGeneratedFile(content)
				if isGen && !applyToGenerated {
					// For generated file without apply, we treat as not needing processing but for list-diff we should list? From earlier tests, for ./... with generated and no apply, file+list-diff did NOT list generated file (only normal). So skip entirely for listing? Actually we need to skip for all operations.
					// tasks should include but marked skip
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: true, skip: true, formattedContent: content})
					return nil
				}
				tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: isGen})
				return nil
			})
			continue
		}
		fi, err := os.Stat(p)
		if err != nil {
			// if file doesn't exist, try as file path anyway
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
			continue
		}
		if fi.IsDir() {
			var dirAbs string
			if filepath.IsAbs(p) {
				dirAbs = p
			} else {
				cwd, _ := os.Getwd()
				dirAbs = filepath.Join(cwd, p)
			}
			if recursive {
				filepath.WalkDir(dirAbs, func(wp string, d fs.DirEntry, err error) error {
					if err != nil {
						return nil
					}
					if d.IsDir() {
						if isExcluded(wp) {
							return filepath.SkipDir
						}
						return nil
					}
					if !strings.HasSuffix(wp, ".go") {
						return nil
					}
					if isExcluded(wp) {
						return nil
					}
					content, err := os.ReadFile(wp)
					if err != nil {
						return nil
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						return nil
					}
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
					return nil
				})
			} else {
				entries, err := os.ReadDir(dirAbs)
				if err != nil {
					continue
				}
				for _, e := range entries {
					if e.IsDir() {
						continue
					}
					if !strings.HasSuffix(e.Name(), ".go") {
						continue
					}
					fp := filepath.Join(dirAbs, e.Name())
					if isExcluded(fp) {
						continue
					}
					content, err := os.ReadFile(fp)
					if err != nil {
						continue
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						continue
					}
					tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
				}
			}
		} else {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
		}
	}

	// project name detection
	projectNameForFile := func(absPath string) (string, error) {
		if projectName != "" {
			return projectName, nil
		}
		dir := filepath.Dir(absPath)
		for {
			goModPath := filepath.Join(dir, "go.mod")
			if _, err := os.Stat(goModPath); err == nil {
				data, err := os.ReadFile(goModPath)
				if err != nil {
					return "", err
				}
				lines := strings.Split(string(data), "\n")
				for _, line := range lines {
					line = strings.TrimSpace(line)
					if strings.HasPrefix(line, "module ") {
						modName := strings.TrimSpace(strings.TrimPrefix(line, "module"))
						return modName, nil
					}
				}
				return "", fmt.Errorf("open go.mod: no such file or directory")
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	anyChangedForExit := false
	hasError := false

	// process each task
	for i := range tasks {
		task := &tasks[i]
		if task.skip {
			task.formattedContent = task.origContent
			task.changed = false
			continue
		}
		projName, err := projectNameForFile(task.absPath)
		if err != nil {
			flag.Usage()
			log.Printf("Could not determine project name for path %s: %v\n", task.relArg, err)
			task.errorOccurred = true
			task.formattedContent = task.origContent
			task.changed = false
			hasError = true
			continue
		}

		fset := token.NewFileSet()
		fileAst, err := parser.ParseFile(fset, task.absPath, task.origContent, parser.ParseComments)
		if err != nil {
			log.Printf("Failed to fix file: file has invalid Go source content, use -excludes flag to skip this file: %s\n", err.Error())
			task.errorOccurred = true
			task.formattedContent = task.origContent
			hasError = true
			continue
		}

		// collect imports
		type impInfo struct {
			Alias string
			Path  string
			Orig  *ast.ImportSpec
		}
		var imps []impInfo
		for _, imp := range fileAst.Imports {
			alias := ""
			if imp.Name != nil {
				alias = imp.Name.Name
			}
			path := ""
			if imp.Path != nil {
				path = strings.Trim(imp.Path.Value, `"`)
				path = strings.Trim(path, "`")
				// also handle backticks
				if len(imp.Path.Value) >= 2 && imp.Path.Value[0] == '`' {
					path = strings.Trim(imp.Path.Value, "`")
				}
			}
			imps = append(imps, impInfo{Alias: alias, Path: path, Orig: imp})
		}

		// rm-unused
		if rmUnused {
			// Collect used package names via selector expressions
			used := make(map[string]bool)
			// Also need to consider dot imports: if dot import, we cannot detect unused, keep it
			// For blank imports, keep
			ast.Inspect(fileAst, func(n ast.Node) bool {
				sel, ok := n.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				if ident, ok := sel.X.(*ast.Ident); ok {
					used[ident.Name] = true
				}
				return true
			})
			// Also, for each file, if there is a dot import, then identifiers without selector may be from that package; we cannot reliably detect, so we keep all dot imports always (already)
			// For blank imports, keep
			var filtered []impInfo
			for _, ii := range imps {
				if ii.Alias == "_" || ii.Alias == "." {
					filtered = append(filtered, ii)
					continue
				}
				localName := ii.Alias
				if localName == "" {
					localName = getPackageNameFromPath(ii.Path)
				}
				if used[localName] {
					filtered = append(filtered, ii)
				}
			}
			imps = filtered
		}

		// set-alias
		if setAlias {
			for idxImp := range imps {
				ii := &imps[idxImp]
				if ii.Alias != "" && ii.Alias != "_" && ii.Alias != "." {
					continue
				}
				if ii.Alias == "_" || ii.Alias == "." {
					continue
				}
				aliasNeeded := getAliasForVersionedPath(ii.Path)
				if aliasNeeded != "" {
					// Check if package name from path's directory matches aliasNeeded? Actually we set alias if package name derived from last dir is version, then alias to previous
					// Also need to ensure aliasNeeded not empty and not equal to version dir
					// For path where last element is version, alias is previous element trimmed.
					// For path where last element has .vN, alias is trimmed.
					ii.Alias = aliasNeeded
				}
			}
		}

		// grouping
		type groupedImp struct {
			Group string
			Imp   impInfo
		}

		var grouped []groupedImp

		// Determine if blanked and dotted groups are present in order
		hasBlanked := false
		hasDotted := false
		for _, g := range orderGroups {
			if g == "blanked" {
				hasBlanked = true
			}
			if g == "dotted" {
				hasDotted = true
			}
		}

		for _, ii := range imps {
			var grp string
			if ii.Alias == "_" {
				if hasBlanked {
					grp = "blanked"
				} else {
					grp = "general"
				}
			} else if ii.Alias == "." {
				if hasDotted {
					grp = "dotted"
				} else {
					grp = "general"
				}
			} else {
				if isProjectImport(ii.Path, projName) {
					grp = "project"
				} else if isCompanyImport(ii.Path, companyPrefixes) {
					grp = "company"
				} else if isStdPackage(ii.Path) {
					grp = "std"
				} else {
					grp = "general"
				}
			}
			grouped = append(grouped, groupedImp{Group: grp, Imp: ii})
		}

		// Now sort groups according to orderGroups
		// Create map group -> list
		groupMap := make(map[string][]impInfo)
		for _, g := range grouped {
			groupMap[g.Group] = append(groupMap[g.Group], g.Imp)
		}

		// For groups not in orderGroups, where should they go? According to original, if import-order has less than required groups it errors, but if it has at least 4, any extra groups like blanked,dotted are optional. For groups not present in order, they should be treated as general? Or ignored? In our earlier test, when order is std,general,company,project (no blanked,dotted), blanked and dotted were mapped to general, so they are not in groupMap as blanked/dotted (we already mapped them to general). So for remaining groups like company when companyPrefixes empty, company group will be empty but still in order.
		// However, if order does NOT contain company (e.g., order is std,project,general,blanked,dotted) it still contains company? Actually we have at least 4 groups, but could be std,project,general,company is still all four, just reordered. If order is std,project,general,company,blanked,dotted, then company is present. If order is std,general,project,blanked,dotted,company, still present. So all four main groups should be present? But original requires at least 4, but could be std,general,company,project plus blanked,dotted. So all main groups are present in default. But if user provides custom order that excludes company? Example order std,general,project (only 3) would error because <4. So custom order must have at least 4. Could it be std,general,project,blanked (4 groups, no company)? Then company group would be missing from order. In that case, where do company imports go? Probably they would be treated as general? Let's check original behavior for order with only some groups: we tested earlier with order std,project only 2 groups and it errored. We tested order std,general (2 groups) errored. We tested order std,general,company,project,blanked (5 groups) succeeded. So order must contain at least the 4 main groups, but could exclude blanked/dotted. If order excludes company (e.g., std,general,project,blanked), it has 4 groups but no company, would it error? The check only checks len<4, not presence of required groups. So std,general,project,blanked would have len 4 and would NOT error, even though company missing. What would happen to company imports then? They would be mapped to group "company" which is not in order, so they might be dropped or treated as general? We should test: we didn't test company missing case. Let's assume company imports would be treated as general if company not in order.
