func addBlankLinesBetweenDecls(src string) []byte {
	// This function adds blank line between top-level declarations
	// We will parse src
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "tmp.go", src, parser.ParseComments)
	if err != nil {
		return []byte(src)
	}
	var buf bytes.Buffer
	// Print package clause
	// The file's package line
	// We'll use printer to print file but with custom handling
	// Actually we can print decls one by one with extra newline

	// Print package clause: "package <name>\n\n"
	buf.WriteString(fmt.Sprintf("package %s\n", file.Name.Name))
	// If there are imports, print them? But this function is called after we already have imports grouped and rest formatted. However we can just handle: if file has import decls, we print them as they appear in file (they are part of Decls)

	// Actually file.Decls includes all top-level decls including imports, funcs, etc.

	// We will print each decl with 1 blank line between

	for i, decl := range file.Decls {
		if i > 0 {
			// Add blank line between decls
			buf.WriteString("\n")
		}
		// Format decl
		var b bytes.Buffer
		printer.Fprint(&b, fset, decl)
		buf.WriteString(b.String())
		buf.WriteString("\n")
	}
	return buf.Bytes()
}

