				}
				trimmed := strings.TrimSuffix(pat, "/")
				if strings.HasPrefix(rel, trimmed+"/") || rel == trimmed {
					return true
				}
				if strings.HasPrefix(absPath, trimmed+"/") || strings.Contains(absPath, "/"+trimmed+"/") || strings.HasSuffix(absPath, "/"+trimmed) {
