		for _, g := range orderGroups {
			impsInGroup := groupMap[g]
			if len(impsInGroup) == 0 {
				continue
			}
			if separateNamed {
				var anon []impInfo
				var named []impInfo
				for _, ii := range impsInGroup {
					if ii.Alias == "" || ii.Alias == "_" || ii.Alias == "." {
						anon = append(anon, ii)
					} else {
						named = append(named, ii)
					}
				}
				if len(anon) > 0 {
					outGroups = append(outGroups, outGroup{Imps: anon})
				}
				if len(named) > 0 {
					outGroups = append(outGroups, outGroup{Imps: named})
				}
			} else {
				outGroups = append(outGroups, outGroup{Imps: impsInGroup})
			}
		}

