			// We will use single line if there is only one import total
			ii := outGroups[0].Imps[0]
			commentStr := ""
			if ii.Orig != nil && ii.Orig.Comment != nil && len(ii.Orig.Comment.List) > 0 {
				var ctexts []string
				for _, c := range ii.Orig.Comment.List {
					ctexts = append(ctexts, c.Text)
				}
				commentStr = " " + strings.Join(ctexts, " ")
			}
			if ii.Alias != "" {
				importBlock.WriteString(fmt.Sprintf("import %s %q%s\n", ii.Alias, ii.Path, commentStr))
			} else {
				importBlock.WriteString(fmt.Sprintf("import %q%s\n", ii.Path, commentStr))
			}
		} else {
			importBlock.WriteString("import (\n")
			for gi, og := range outGroups {
				if gi > 0 {
					importBlock.WriteString("\n")
				}
				for _, ii := range og.Imps {
					commentStr := ""
					if ii.Orig != nil && ii.Orig.Comment != nil {
						var ctexts []string
						for _, c := range ii.Orig.Comment.List {
							ctexts = append(ctexts, c.Text)
						}
						if len(ctexts) > 0 {
							commentStr = " " + strings.Join(ctexts, " ")
						}
					}
					if ii.Alias != "" {
						importBlock.WriteString(fmt.Sprintf("\t%s %q%s\n", ii.Alias, ii.Path, commentStr))
					} else {
						importBlock.WriteString(fmt.Sprintf("\t%q%s\n", ii.Path, commentStr))
					}
				}
			}
			importBlock.WriteString(")\n")
		}

