		var filteredComments []*ast.CommentGroup
		for _, cg := range fileAst.Comments {
			// If comment is inside any import range, skip
			inside := false
			for _, r := range importRanges {
				if cg.Pos() >= r[0] && cg.End() <= r[1] {
					inside = true
					break
				}
			}
			if !inside {
				filteredComments = append(filteredComments, cg)
			}
		}

		var newDeclsNoImport []ast.Decl
		for _, d := range fileAst.Decls {
			if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
				continue
			}
			newDeclsNoImport = append(newDeclsNoImport, d)
		}
		newFileNoImport := &ast.File{
			Package:  fileAst.Package,
			Name:     fileAst.Name,
			Decls:    newDeclsNoImport,
			Comments: filteredComments,
			Doc:      fileAst.Doc,
		}
		var bufNoImport bytes.Buffer
		cfg := printer.Config{Mode: printer.TabIndent | printer.UseSpaces, Tabwidth: 8}
		err = cfg.Fprint(&bufNoImport, fset, newFileNoImport)
		if err != nil {
			task.formattedContent = task.origContent
			task.changed = false
			continue
		}
		restFormatted := bufNoImport.String()

		// Insert import block
		// restFormatted starts with package line
		parts := strings.SplitN(restFormatted, "\n", 2)
		var finalBuilder strings.Builder
		if len(parts) >= 1 {
			finalBuilder.WriteString(parts[0])
			finalBuilder.WriteString("\n")
		}
		if importBlock.Len() > 0 {
			finalBuilder.WriteString("\n")
			finalBuilder.WriteString(importBlock.String())
			if len(parts) == 2 {
				rem := strings.TrimLeft(parts[1], "\n")
				if rem != "" {
					finalBuilder.WriteString("\n")
					finalBuilder.WriteString(rem)
				}
			}
		} else {
			if len(parts) == 2 {
				finalBuilder.WriteString("\n")
				finalBuilder.WriteString(parts[1])
			}
		}
		formattedStr := finalBuilder.String()
		if !strings.HasSuffix(formattedStr, "\n") {
			formattedStr += "\n"
		}
		if formatFlag {
			formattedStr = string(addBlankLinesBetweenDecls(formattedStr))
		}
		task.formattedContent = []byte(formattedStr)
		if !bytes.Equal(task.origContent, task.formattedContent) {
			task.changed = true
			anyChangedForExit = true
		} else {
			task.changed = false
		}
	}

	if filePath != "" {
		log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
	}
	if localStr != "" {
		log.Printf("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
	}

	// Output
	for _, task := range tasks {
		if task.skip || task.errorOccurred {
			continue
		}
		if outputMode == "file" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		} else if outputMode == "stdout" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					if task.changed {
						fmt.Println(task.absPath)
					} else {
						fmt.Print(string(task.formattedContent))
					}
				}
			} else {
				if task.isDotDot {
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				} else {
					fmt.Print(string(task.formattedContent))
				}
			}
		} else if outputMode == "write" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		}
	}

	if setExitStatus {
		if anyChangedForExit {
			os.Exit(1)
		}
	}
	if hasError {
		os.Exit(1)
	}
}
