					}
					return nil
				}
				if !strings.HasSuffix(wp, ".go") {
					return nil
				}
				if isExcluded(wp) {
					return nil
				}
				content, err := os.ReadFile(wp)
				if err != nil {
					return nil
				}
				isGen := isGeneratedFile(content)
				if isGen && !applyToGenerated {
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: true, skip: true, formattedContent: content})
					return nil
				}
				tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: isGen})
				return nil
			})
			continue
		}
		fi, err := os.Stat(p)
		if err != nil {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
			continue
		}
		if fi.IsDir() {
			var dirAbs string
			if filepath.IsAbs(p) {
				dirAbs = p
			} else {
				cwd, _ := os.Getwd()
				dirAbs = filepath.Join(cwd, p)
			}
			if recursive {
				filepath.WalkDir(dirAbs, func(wp string, d fs.DirEntry, err error) error {
					if err != nil {
						return nil
					}
					if d.IsDir() {
						if isExcluded(wp) {
							return filepath.SkipDir
						}
						return nil
					}
					if !strings.HasSuffix(wp, ".go") {
						return nil
					}
					if isExcluded(wp) {
						return nil
					}
					content, err := os.ReadFile(wp)
					if err != nil {
						return nil
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						return nil
					}
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
					return nil
				})
			} else {
				entries, err := os.ReadDir(dirAbs)
				if err != nil {
					continue
				}
				for _, e := range entries {
					if e.IsDir() {
						continue
					}
					if !strings.HasSuffix(e.Name(), ".go") {
						continue
					}
					fp := filepath.Join(dirAbs, e.Name())
					if isExcluded(fp) {
						continue
					}
					content, err := os.ReadFile(fp)
					if err != nil {
						continue
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						continue
					}
					tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
				}
			}
		} else {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
		}
	}

	projectNameForFile := func(absPath string) (string, error) {
		if projectName != "" {
			return projectName, nil
		}
		dir := filepath.Dir(absPath)
		for {
			goModPath := filepath.Join(dir, "go.mod")
			if _, err := os.Stat(goModPath); err == nil {
				data, err := os.ReadFile(goModPath)
				if err != nil {
					return "", err
				}
				lines := strings.Split(string(data), "\n")
				for _, line := range lines {
					line = strings.TrimSpace(line)
					if strings.HasPrefix(line, "module ") {
						modName := strings.TrimSpace(strings.TrimPrefix(line, "module"))
						return modName, nil
					}
				}
				return "", fmt.Errorf("open go.mod: no such file or directory")
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	anyChangedForExit := false
	hasError := false

	for i := range tasks {
		task := &tasks[i]
		if task.skip {
			task.formattedContent = task.origContent
			task.changed = false
			continue
		}
		projName, err := projectNameForFile(task.absPath)
		if err != nil {
			flag.Usage()
			log.Printf("Could not determine project name for path %s: %v\n", task.relArg, err)
			task.errorOccurred = true
			task.formattedContent = task.origContent
			hasError = true
			continue
		}

		fset := token.NewFileSet()
		fileAst, err := parser.ParseFile(fset, task.absPath, task.origContent, parser.ParseComments)
		if err != nil {
			log.Printf("Failed to fix file: file has invalid Go source content, use -excludes flag to skip this file: %s\n", err.Error())
			task.errorOccurred = true
			task.formattedContent = task.origContent
			hasError = true
			continue
		}

		type impInfo struct {
			Alias string
			Path  string
			Orig  *ast.ImportSpec
		}
		var imps []impInfo
		for _, imp := range fileAst.Imports {
			alias := ""
			if imp.Name != nil {
				alias = imp.Name.Name
			}
			path := ""
			if imp.Path != nil {
				v := imp.Path.Value
				if len(v) >= 2 {
					if v[0] == '"' || v[0] == '`' {
						path = v[1 : len(v)-1]
					} else {
						path = v
					}
				}
			}
			imps = append(imps, impInfo{Alias: alias, Path: path, Orig: imp})
		}

		if rmUnused {
			used := make(map[string]bool)
			ast.Inspect(fileAst, func(n ast.Node) bool {
				sel, ok := n.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				if ident, ok := sel.X.(*ast.Ident); ok {
					used[ident.Name] = true
				}
				return true
			})
			var filtered []impInfo
			for _, ii := range imps {
				if ii.Alias == "_" || ii.Alias == "." {
					filtered = append(filtered, ii)
					continue
				}
				localName := ii.Alias
				if localName == "" {
					localName = getPackageNameFromPath(ii.Path)
				}
				if used[localName] {
					filtered = append(filtered, ii)
				}
			}
			imps = filtered
		}

		if setAlias {
			for idxImp := range imps {
				ii := &imps[idxImp]
				if ii.Alias != "" && ii.Alias != "_" && ii.Alias != "." {
					continue
				}
				if ii.Alias == "_" || ii.Alias == "." {
					continue
				}
				aliasNeeded := getAliasForVersionedPath(ii.Path)
				if aliasNeeded != "" {
					ii.Alias = aliasNeeded
				}
			}
		}

		type groupedImp struct {
			Group string
			Imp   impInfo
		}
		var grouped []groupedImp
		hasBlanked := false
		hasDotted := false
		for _, g := range orderGroups {
			if g == "blanked" {
				hasBlanked = true
			}
			if g == "dotted" {
				hasDotted = true
			}
		}
		for _, ii := range imps {
			var grp string
			if ii.Alias == "_" {
				if hasBlanked {
					grp = "blanked"
				} else {
					grp = "general"
				}
			} else if ii.Alias == "." {
				if hasDotted {
					grp = "dotted"
				} else {
					grp = "general"
				}
			} else {
				if isProjectImport(ii.Path, projName) {
					grp = "project"
				} else if isCompanyImport(ii.Path, companyPrefixes) {
					grp = "company"
				} else if isStdPackage(ii.Path) {
					grp = "std"
				} else {
					grp = "general"
				}
			}
			grouped = append(grouped, groupedImp{Group: grp, Imp: ii})
		}

		orderIndex := make(map[string]int)
		for idx, g := range orderGroups {
			orderIndex[g] = idx
		}
		groupMap := make(map[string][]impInfo)
		for _, gi := range grouped {
			desired := gi.Group
			if _, ok := orderIndex[desired]; !ok {
				if _, ok2 := orderIndex["general"]; ok2 {
					desired = "general"
				} else {
					desired = orderGroups[0]
				}
			}
			groupMap[desired] = append(groupMap[desired], gi.Imp)
		}
		for _, g := range orderGroups {
			impsInGroup := groupMap[g]
			sort.Slice(impsInGroup, func(i, j int) bool {
				if impsInGroup[i].Path != impsInGroup[j].Path {
					return impsInGroup[i].Path < impsInGroup[j].Path
				}
				return impsInGroup[i].Alias < impsInGroup[j].Alias
			})
			groupMap[g] = impsInGroup
		}

		type outGroup struct {
			Imps []impInfo
		}
		var outGroups []outGroup
		for _, g := range orderGroups {
			impsInGroup := groupMap[g]
			if len(impsInGroup) == 0 {
				continue
			}
			if separateNamed {
				var anon []impInfo
				var named []impInfo
				for _, ii := range impsInGroup {
					if ii.Alias == "" || ii.Alias == "_" || ii.Alias == "." {
						anon = append(anon, ii)
					} else {
						named = append(named, ii)
					}
				}
				if len(anon) > 0 {
					outGroups = append(outGroups, outGroup{Imps: anon})
				}
				if len(named) > 0 {
					outGroups = append(outGroups, outGroup{Imps: named})
				}
			} else {
				outGroups = append(outGroups, outGroup{Imps: impsInGroup})
			}
		}

		// Build file with new imports using AST
		var newSpecs []ast.Spec
		for _, og := range outGroups {
			for _, ii := range og.Imps {
				spec := &ast.ImportSpec{
					Path: &ast.BasicLit{Kind: token.STRING, Value: fmt.Sprintf("%q", ii.Path)},
				}
				if ii.Alias != "" {
					spec.Name = &ast.Ident{Name: ii.Alias}
				}
				// Preserve original Doc for preceding comments? Not trailing, to avoid duplication we will not copy Comment
				// We will handle trailing comments separately
				if ii.Orig != nil && ii.Orig.Doc != nil {
					// Doc is usually preceding comment (like // comment line before import)
					// We keep it
					spec.Doc = ii.Orig.Doc
				}
				// For trailing comment, we will keep it via custom block generation later, not via AST, so we don't copy Comment here for printer, but we will handle manually
				// Actually if we copy Comment, printer will print it, and our manual block also prints it, causing duplicate. So we keep Comment nil for printer, and handle manually.
				newSpecs = append(newSpecs, spec)
			}
		}

		var newDecls []ast.Decl
		for _, d := range fileAst.Decls {
			if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
				continue
			}
			newDecls = append(newDecls, d)
		}

		// Filter comments that belong to imports
		var importRanges [][2]token.Pos
		for _, decl := range fileAst.Decls {
			if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
				importRanges = append(importRanges, [2]token.Pos{gen.Pos(), gen.End()})
			}
		}
		var filteredComments []*ast.CommentGroup
		for _, cg := range fileAst.Comments {
			inside := false
			for _, r := range importRanges {
				if cg.Pos() >= r[0] && cg.End() <= r[1] {
					// Check if this comment is trailing comment that we already handle? We will skip all import comments to avoid duplication
					inside = true
					break
				}
			}
			if !inside {
				filteredComments = append(filteredComments, cg)
			}
		}

		var formattedWithoutGroupBlanks string
		if len(newSpecs) == 0 {
			// No imports
			newFile := &ast.File{
				Package:  fileAst.Package,
				Name:     fileAst.Name,
				Decls:    newDecls,
				Comments: filteredComments,
				Doc:      fileAst.Doc,
			}
			var buf bytes.Buffer
			cfg := printer.Config{Mode: printer.TabIndent | printer.UseSpaces, Tabwidth: 8}
			cfg.Fprint(&buf, fset, newFile)
			formattedWithoutGroupBlanks = buf.String()
		} else {
			// Build file with imports
			newImportDecl := &ast.GenDecl{Tok: token.IMPORT, Specs: newSpecs}
			if len(newSpecs) > 1 {
				newImportDecl.Lparen = 1
			}
			newFile := &ast.File{
				Package:  fileAst.Package,
				Name:     fileAst.Name,
				Decls:    append([]ast.Decl{newImportDecl}, newDecls...),
				Comments: filteredComments,
				Doc:      fileAst.Doc,
			}
			var buf bytes.Buffer
			cfg := printer.Config{Mode: printer.TabIndent | printer.UseSpaces, Tabwidth: 8}
			cfg.Fprint(&buf, fset, newFile)
			formattedWithoutGroupBlanks = buf.String()
		}

		// Now construct import block with blank lines between outGroups
		var customImportBlock strings.Builder
		if len(outGroups) == 0 {
			// nothing
		} else if len(outGroups) == 1 && len(outGroups[0].Imps) == 1 && len(fileAst.Imports) <= 1 {
			// Check if we should use single import line
			// To decide, we need to see if formattedWithoutGroupBlanks has "import (" or single import
			// For simplicity, if only one import, we will generate single line import if original had single line? But we will generate block if more than one group? Since only one group with one import, we can generate single line
			ii := outGroups[0].Imps[0]
			commentStr := ""
			if ii.Orig != nil && ii.Orig.Comment != nil && len(ii.Orig.Comment.List) > 0 {
				var ctexts []string
				for _, c := range ii.Orig.Comment.List {
					ctexts = append(ctexts, c.Text)
				}
				commentStr = " " + strings.Join(ctexts, " ")
			}
			if ii.Alias != "" {
				customImportBlock.WriteString(fmt.Sprintf("import %s %q%s\n", ii.Alias, ii.Path, commentStr))
			} else {
				customImportBlock.WriteString(fmt.Sprintf("import %q%s\n", ii.Path, commentStr))
			}
		} else {
			customImportBlock.WriteString("import (\n")
			for gi, og := range outGroups {
				if gi > 0 {
					customImportBlock.WriteString("\n")
				}
				for _, ii := range og.Imps {
					commentStr := ""
					if ii.Orig != nil && ii.Orig.Comment != nil {
						var ctexts []string
						for _, c := range ii.Orig.Comment.List {
							ctexts = append(ctexts, c.Text)
						}
						if len(ctexts) > 0 {
							commentStr = " " + strings.Join(ctexts, " ")
						}
					}
					if ii.Alias != "" {
						customImportBlock.WriteString(fmt.Sprintf("\t%s %q%s\n", ii.Alias, ii.Path, commentStr))
					} else {
						customImportBlock.WriteString(fmt.Sprintf("\t%q%s\n", ii.Path, commentStr))
					}
				}
			}
			customImportBlock.WriteString(")\n")
		}

		// Replace import block in formattedWithoutGroupBlanks with customImportBlock
		finalStr := formattedWithoutGroupBlanks
		if customImportBlock.Len() > 0 {
			// Find import block
			// Look for "import (" and then matching ")\n"
			// Simpler: find first occurrence of "import ("
			idxStart := strings.Index(finalStr, "import (")
			if idxStart != -1 {
				// Find the closing ")\n" after idxStart
				// Need to find matching parenthesis, but simple: find next "\n)\n" or "\n)\n\n"
				// We'll search for ")\n" after idxStart
				rest := finalStr[idxStart:]
				// Find the first "\n)\n" or "\n)" 
				// Use a simple approach: find last occurrence of "\n)\n" before next decl? Actually we have only one import block at top.
				// We'll find the closing by counting parens? But imports don't have nested parens.
				// So find first "\n)\n" after "import ("
				endIdx := strings.Index(rest, "\n)\n")
				if endIdx == -1 {
					endIdx = strings.Index(rest, "\n)")
				}
				if endIdx != -1 {
					// endIdx is within rest, includes "\n"
					// We want to replace from idxStart to idxStart+endIdx+ len("\n)\n")?
					// Determine length of closing
					var closingLen int
					if strings.HasPrefix(rest[endIdx:], "\n)\n") {
						closingLen = len("\n)\n")
					} else {
						closingLen = len("\n)")
						// May need following newline
						if len(rest) > endIdx+2 && rest[endIdx+2] == '\n' {
							closingLen = 3
						}
					}
					before := finalStr[:idxStart]
					after := finalStr[idxStart+endIdx+closingLen:]
					finalStr = before + customImportBlock.String() + after
				} else {
					// No parens block found, maybe single import? Replace single import line
					// Find "import " line
					lines := strings.Split(finalStr, "\n")
					var newLines []string
					replaced := false
					for _, line := range lines {
						if !replaced && strings.HasPrefix(strings.TrimSpace(line), "import ") {
							newLines = append(newLines, strings.TrimSuffix(customImportBlock.String(), "\n"))
							replaced = true
						} else {
							newLines = append(newLines, line)
						}
					}
					finalStr = strings.Join(newLines, "\n")
				}
			} else {
				// Check for single import
				idxSingle := strings.Index(finalStr, "import ")
				if idxSingle != -1 {
					// Find end of line
					endLine := strings.Index(finalStr[idxSingle:], "\n")
					if endLine != -1 {
						before := finalStr[:idxSingle]
						after := finalStr[idxSingle+endLine+1:]
						finalStr = before + customImportBlock.String() + after
					} else {
						finalStr = finalStr[:idxSingle] + customImportBlock.String()
					}
				} else {
					// No import found, need to insert after package
					// Find package line
					parts := strings.SplitN(finalStr, "\n", 2)
					if len(parts) == 2 {
						finalStr = parts[0] + "\n\n" + customImportBlock.String() + "\n" + parts[1]
					} else {
						finalStr = finalStr + "\n" + customImportBlock.String()
					}
				}
			}
		} else {
			// No imports, finalStr already has no imports
		}

		if formatFlag {
			finalStr = addBlankLinesBetweenDecls(finalStr)
		}

		// Ensure final newline
		if !strings.HasSuffix(finalStr, "\n") {
			finalStr += "\n"
		}

		task.formattedContent = []byte(finalStr)
		if !bytes.Equal(task.origContent, task.formattedContent) {
			task.changed = true
			anyChangedForExit = true
		}
	}

	if filePath != "" {
		log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
	}
	if localStr != "" {
		log.Printf("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
	}

	for _, task := range tasks {
		if task.skip || task.errorOccurred {
			continue
		}
		if outputMode == "file" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		} else if outputMode == "stdout" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					if task.changed {
						fmt.Println(task.absPath)
					} else {
						fmt.Print(string(task.formattedContent))
					}
				}
			} else {
				if task.isDotDot {
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				} else {
					fmt.Print(string(task.formattedContent))
				}
			}
		} else if outputMode == "write" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		}
	}

	if setExitStatus {
		if anyChangedForExit {
			os.Exit(1)
		}
	}
	if hasError {
		os.Exit(1)
	}
}
GO
go build -o /tmp/newexec . 2>&1
echo build $?
/tmp/newexec -version 2>&1
"}

