actions.command:
cd /workspace
# Update main.go with corrected grouping and separateNamed logic

cat > main.go <<'GO'
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const versionStr = "3.0.0-20260611193416-a37f51062178"
const builtWith = "go1.26.0"

func isGeneratedFile(content []byte) bool {
	s := string(content)
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		if trim == "" {
			continue
		}
		if strings.HasPrefix(trim, "//") {
			if strings.HasPrefix(trim, "// Code generated") {
				return true
			}
			return false
		}
		return false
	}
	return false
}

func isVersionDir(s string) bool {
	if len(s) < 2 {
		return false
	}
	if s[0] != 'v' {
		return false
	}
	for _, c := range s[1:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func trimVersionSuffix(s string) string {
	idx := strings.LastIndex(s, ".")
	if idx == -1 {
		return s
	}
	suf := s[idx+1:]
	if isVersionDir(suf) {
		return s[:idx]
	}
	return s
}

func getPackageNameFromPath(path string) string {
	path = strings.TrimSuffix(path, "/")
	if path == "" {
		return ""
	}
	parts := strings.Split(path, "/")
	last := parts[len(parts)-1]
	if isVersionDir(last) {
		if len(parts) >= 2 {
			prev := parts[len(parts)-2]
			return trimVersionSuffix(prev)
		}
		return last
	}
	return trimVersionSuffix(last)
}

func getAliasForVersionedPath(path string) string {
	path = strings.TrimSuffix(path, "/")
	parts := strings.Split(path, "/")
	if len(parts) == 0 {
		return ""
	}
	last := parts[len(parts)-1]
	if isVersionDir(last) {
		if len(parts) >= 2 {
			prev := parts[len(parts)-2]
			alias := trimVersionSuffix(prev)
			if alias == "" {
				alias = prev
			}
			return alias
		}
		return ""
	}
	if strings.Contains(last, ".v") {
		idx := strings.LastIndex(last, ".")
		if idx != -1 {
			suf := last[idx+1:]
			if isVersionDir(suf) {
				return last[:idx]
			}
		}
	}
	return ""
}

func isStdPackage(path string) bool {
	return !strings.Contains(path, ".")
}

func isProjectImport(path, projectName string) bool {
	if projectName == "" {
		return false
	}
	if strings.HasSuffix(projectName, "/") {
		return false
	}
	if path == projectName {
		return true
	}
	if strings.HasPrefix(path, projectName+"/") {
		return true
	}
	return false
}

func isCompanyImport(path string, companyPrefixes []string) bool {
	if len(companyPrefixes) == 0 {
		return false
	}
	for _, cp := range companyPrefixes {
		if cp == "" {
			continue
		}
		if strings.HasPrefix(path, cp) {
			return true
		}
	}
	return false
}

func addBlankLinesBetweenDecls(src string) string {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "tmp.go", src, parser.ParseComments)
	if err != nil {
		return src
	}
	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("package %s\n", file.Name.Name))
	if len(file.Decls) > 0 {
		buf.WriteString("\n")
	}
	for i, decl := range file.Decls {
		if i > 0 {
			buf.WriteString("\n")
		}
		var b bytes.Buffer
		printer.Fprint(&b, fset, decl)
		buf.WriteString(b.String())
		buf.WriteString("\n")
	}
	return buf.String()
}

func main() {
	var (
		applyToGenerated   bool
		companyPrefixesStr string
		excludesStr        string
		filePath           string
		formatFlag         bool
		importsOrderStr    string
		listDiff           bool
		localStr           string
		outputStr          string
		projectName        string
		recursive          bool
		rmUnused           bool
		separateNamed      bool
		setAlias           bool
		setExitStatus      bool
		useCache           bool
		showVersion        bool
		showVersionOnly    bool
	)
	flag.BoolVar(&applyToGenerated, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&companyPrefixesStr, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&excludesStr, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&filePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&formatFlag, "format", false, "Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&importsOrderStr, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	flag.BoolVar(&listDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&localStr, "local", "", "Deprecated")
	flag.StringVar(&outputStr, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&projectName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&rmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	flag.BoolVar(&separateNamed, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&setAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&setExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&useCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&showVersion, "version", false, "Show version information")
	flag.BoolVar(&showVersionOnly, "version-only", false, "Show only the version string")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	if showVersion {
		fmt.Printf("version: %s\n", versionStr)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", versionStr)
		fmt.Printf("commit: n/a\n")
		fmt.Printf("source: github.com/incu6us/goimports-reviser/v3\n")
		return
	}
	if showVersionOnly {
		fmt.Println(versionStr)
		return
	}

	orderGroups := []string{}
	if importsOrderStr != "" {
		for _, part := range strings.Split(importsOrderStr, ",") {
			t := strings.TrimSpace(part)
			if t == "" {
				continue
			}
			orderGroups = append(orderGroups, t)
		}
		if len(orderGroups) < 4 {
			flag.Usage()
			log.Fatalf("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
		}
		allowed := map[string]bool{"std": true, "general": true, "company": true, "project": true, "blanked": true, "dotted": true}
		for _, g := range orderGroups {
			if !allowed[g] {
				flag.Usage()
				log.Fatalf("unknown order group type: \"%s\"", g)
			}
		}
	} else {
		orderGroups = []string{"std", "general", "company", "project"}
	}

	args := flag.Args()
	var paths []string
	if filePath != "" {
		paths = append(paths, filePath)
	}
	paths = append(paths, args...)

	if len(paths) == 0 {
		flag.Usage()
		log.Println("no file(s) or directory(ies) specified on input")
		return
	}

	log.Printf("Paths: %v\n", paths)

	var companyPrefixes []string
	if companyPrefixesStr != "" {
		for _, cp := range strings.Split(companyPrefixesStr, ",") {
			cp = strings.TrimSpace(cp)
			if cp != "" {
				companyPrefixes = append(companyPrefixes, cp)
			}
		}
	}

	var excludePatterns []string
	if excludesStr != "" {
		for _, ep := range strings.Split(excludesStr, ",") {
			ep = strings.TrimSpace(ep)
			if ep != "" {
				excludePatterns = append(excludePatterns, ep)
			}
		}
	}

	isExcluded := func(absPath string) bool {
		cwd, _ := os.Getwd()
		rel, err := filepath.Rel(cwd, absPath)
		if err != nil {
			rel = absPath
		}
		for _, pat := range excludePatterns {
			if strings.HasSuffix(pat, "/") {
				if strings.HasPrefix(rel, pat) || strings.HasPrefix(absPath, pat) || strings.Contains(rel, pat) || strings.Contains(absPath, pat) {
					return true
				}
				trimmed := strings.TrimSuffix(pat, "/")
				if strings.HasPrefix(rel, trimmed+"/") || rel == trimmed {
					return true
				}
				continue
			}
			if ok, _ := filepath.Match(pat, rel); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, absPath); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, filepath.ToSlash(rel)); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, filepath.ToSlash(absPath)); ok {
				return true
			}
		}
		return false
	}

	outputMode := outputStr
	if outputMode != "file" && outputMode != "stdout" && outputMode != "write" {
		outputMode = "file"
	}

	type fileTask struct {
		absPath          string
		relArg           string
		isDotDot         bool
		origContent      []byte
		formattedContent []byte
		changed          bool
		skip             bool
		isGenerated      bool
		errorOccurred    bool
	}

	var tasks []fileTask

	for _, p := range paths {
		log.Printf("Processing %s\n", p)
		if strings.Contains(p, "...") {
			base := strings.Split(p, "...")[0]
			base = strings.TrimSpace(base)
			if base == "" {
				base = "."
			}
			base = strings.TrimSuffix(base, "/")
			if base == "" {
				base = "."
			}
			var baseAbs string
			if filepath.IsAbs(base) {
				baseAbs = base
			} else {
				cwd, _ := os.Getwd()
				baseAbs = filepath.Join(cwd, base)
			}
			filepath.WalkDir(baseAbs, func(wp string, d fs.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if d.IsDir() {
					if isExcluded(wp) {
						return filepath.SkipDir
					}
					return nil
				}
				if !strings.HasSuffix(wp, ".go") {
					return nil
				}
				if isExcluded(wp) {
					return nil
				}
				content, err := os.ReadFile(wp)
				if err != nil {
					return nil
				}
				isGen := isGeneratedFile(content)
				if isGen && !applyToGenerated {
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: true, skip: true, formattedContent: content})
					return nil
				}
				tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: isGen})
				return nil
			})
			continue
		}
		fi, err := os.Stat(p)
		if err != nil {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
			continue
		}
		if fi.IsDir() {
			var dirAbs string
			if filepath.IsAbs(p) {
				dirAbs = p
			} else {
				cwd, _ := os.Getwd()
				dirAbs = filepath.Join(cwd, p)
			}
			if recursive {
				filepath.WalkDir(dirAbs, func(wp string, d fs.DirEntry, err error) error {
					if err != nil {
						return nil
					}
					if d.IsDir() {
						if isExcluded(wp) {
							return filepath.SkipDir
						}
						return nil
					}
					if !strings.HasSuffix(wp, ".go") {
						return nil
					}
					if isExcluded(wp) {
						return nil
					}
					content, err := os.ReadFile(wp)
					if err != nil {
						return nil
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						return nil
					}
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
					return nil
				})
			} else {
				entries, err := os.ReadDir(dirAbs)
				if err != nil {
					continue
				}
				for _, e := range entries {
					if e.IsDir() {
						continue
					}
					if !strings.HasSuffix(e.Name(), ".go") {
						continue
					}
					fp := filepath.Join(dirAbs, e.Name())
					if isExcluded(fp) {
						continue
					}
					content, err := os.ReadFile(fp)
					if err != nil {
						continue
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						continue
					}
					tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
				}
			}
		} else {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
		}
	}

	projectNameForFile := func(absPath string) (string, error) {
		if projectName != "" {
			return projectName, nil
		}
		dir := filepath.Dir(absPath)
		for {
			goModPath := filepath.Join(dir, "go.mod")
			if _, err := os.Stat(goModPath); err == nil {
				data, err := os.ReadFile(goModPath)
				if err != nil {
					return "", err
				}
				lines := strings.Split(string(data), "\n")
				for _, line := range lines {
					line = strings.TrimSpace(line)
					if strings.HasPrefix(line, "module ") {
						modName := strings.TrimSpace(strings.TrimPrefix(line, "module"))
						return modName, nil
					}
				}
				return "", fmt.Errorf("open go.mod: no such file or directory")
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	anyChangedForExit := false
	hasError := false

	for i := range tasks {
		task := &tasks[i]
		if task.skip {
			task.formattedContent = task.origContent
			task.changed = false
			continue
		}
		projName, err := projectNameForFile(task.absPath)
		if err != nil {
			flag.Usage()
			log.Printf("Could not determine project name for path %s: %v\n", task.relArg, err)
			task.errorOccurred = true
			task.formattedContent = task.origContent
			hasError = true
			continue
		}

		fset := token.NewFileSet()
		fileAst, err := parser.ParseFile(fset, task.absPath, task.origContent, parser.ParseComments)
		if err != nil {
			log.Printf("Failed to fix file: file has invalid Go source content, use -excludes flag to skip this file: %s\n", err.Error())
			task.errorOccurred = true
			task.formattedContent = task.origContent
			hasError = true
			continue
		}

		type impInfo struct {
			Alias string
			Path  string
			Orig  *ast.ImportSpec
		}
		var imps []impInfo
		for _, imp := range fileAst.Imports {
			alias := ""
			if imp.Name != nil {
				alias = imp.Name.Name
			}
			path := ""
			if imp.Path != nil {
				v := imp.Path.Value
				if len(v) >= 2 {
					path = v[1 : len(v)-1]
				}
			}
			imps = append(imps, impInfo{Alias: alias, Path: path, Orig: imp})
		}

		if rmUnused {
			used := make(map[string]bool)
			ast.Inspect(fileAst, func(n ast.Node) bool {
				sel, ok := n.(*ast.SelectorExpr)
				if !ok {
					return true
				}
				if ident, ok := sel.X.(*ast.Ident); ok {
					used[ident.Name] = true
				}
				return true
			})
			var filtered []impInfo
			for _, ii := range imps {
				if ii.Alias == "_" || ii.Alias == "." {
					filtered = append(filtered, ii)
					continue
				}
				localName := ii.Alias
				if localName == "" {
					localName = getPackageNameFromPath(ii.Path)
				}
				if used[localName] {
					filtered = append(filtered, ii)
				}
			}
			imps = filtered
		}

		if setAlias {
			for idxImp := range imps {
				ii := &imps[idxImp]
				if ii.Alias != "" && ii.Alias != "_" && ii.Alias != "." {
					continue
				}
				if ii.Alias == "_" || ii.Alias == "." {
					continue
				}
				aliasNeeded := getAliasForVersionedPath(ii.Path)
				if aliasNeeded != "" {
					ii.Alias = aliasNeeded
				}
			}
		}

		// Determine if blanked/dotted groups are requested
		hasBlanked := false
		hasDotted := false
		for _, g := range orderGroups {
			if g == "blanked" {
				hasBlanked = true
			}
			if g == "dotted" {
				hasDotted = true
			}
		}

		// First determine underlying group for each import (std/general/company/project) ignoring blanked/dotted alias
		type underlyingGroup struct {
			Underlying string // std, general, company, project
			Imp        impInfo
		}
		var underlying []underlyingGroup
		for _, ii := range imps {
			var under string
			if isProjectImport(ii.Path, projName) {
				under = "project"
			} else if isCompanyImport(ii.Path, companyPrefixes) {
				under = "company"
			} else if isStdPackage(ii.Path) {
				under = "std"
			} else {
				under = "general"
			}
			underlying = append(underlying, underlyingGroup{Underlying: under, Imp: ii})
		}

		// Now determine final group based on alias and whether blanked/dotted in order
		type groupedImp struct {
			Group string
			Imp   impInfo
			Under string
		}
		var grouped []groupedImp
		for _, ug := range underlying {
			ii := ug.Imp
			var grp string
			if ii.Alias == "_" {
				if hasBlanked {
					grp = "blanked"
				} else {
					grp = ug.Underlying
				}
			} else if ii.Alias == "." {
				if hasDotted {
					grp = "dotted"
				} else {
					grp = ug.Underlying
				}
			} else {
				grp = ug.Underlying
			}
			grouped = append(grouped, groupedImp{Group: grp, Imp: ii, Under: ug.Underlying})
		}

		orderIndex := make(map[string]int)
		for idx, g := range orderGroups {
			orderIndex[g] = idx
		}
		groupMap := make(map[string][]impInfo)
		for _, gi := range grouped {
			desired := gi.Group
			if _, ok := orderIndex[desired]; !ok {
				if _, ok2 := orderIndex["general"]; ok2 {
					desired = "general"
				} else {
					desired = orderGroups[0]
				}
			}
			groupMap[desired] = append(groupMap[desired], gi.Imp)
		}
		for _, g := range orderGroups {
			impsInGroup := groupMap[g]
			sort.Slice(impsInGroup, func(i, j int) bool {
				if impsInGroup[i].Path != impsInGroup[j].Path {
					return impsInGroup[i].Path < impsInGroup[j].Path
				}
				return impsInGroup[i].Alias < impsInGroup[j].Alias
			})
			groupMap[g] = impsInGroup
		}

		type outGroup struct {
			GroupName string
			Imps      []impInfo
			Under     string // for underlying grouping when needed?
		}
		var outGroups []outGroup
		for _, g := range orderGroups {
			impsInGroup := groupMap[g]
			if len(impsInGroup) == 0 {
				continue
			}
			if separateNamed {
				// If group is blanked or dotted, do not split
				if g == "blanked" || g == "dotted" {
					outGroups = append(outGroups, outGroup{GroupName: g, Imps: impsInGroup})
					continue
				}
				// When blanked/dotted NOT in order, they are in underlying groups, and we want to split anon vs aliased (where aliased includes named+blanked+dotted)
				if !hasBlanked || !hasDotted {
					// If blanked or dotted not in order, check if group contains any blanked/dotted that were mapped to this group
					// If so, split as anon vs aliased (aliased = all with alias != "")
					// To determine if group has blanked/dotted mapped, we need to see if any import in group has alias "_" or "."
					hasAliasedBlank := false
					for _, ii := range impsInGroup {
						if ii.Alias == "_" || ii.Alias == "." {
							hasAliasedBlank = true
							break
						}
						if ii.Alias != "" {
							// named
							hasAliasedBlank = false
						}
					}
					_ = hasAliasedBlank
				}
				if !hasBlanked && !hasDotted {
					// Default case: split anon (alias == "") vs aliased (alias != "")
					var anon []impInfo
					var aliased []impInfo
					for _, ii := range impsInGroup {
						if ii.Alias == "" {
							anon = append(anon, ii)
						} else {
							aliased = append(aliased, ii)
						}
					}
					if len(anon) > 0 {
						outGroups = append(outGroups, outGroup{GroupName: g, Imps: anon})
					}
					if len(aliased) > 0 {
						outGroups = append(outGroups, outGroup{GroupName: g, Imps: aliased})
					}
				} else if hasBlanked && hasDotted {
					// Both blanked and dotted are separate groups, so current g is std/general/company/project, contains only anon and named
					var anon []impInfo
					var named []impInfo
					for _, ii := range impsInGroup {
						if ii.Alias == "" {
							anon = append(anon, ii)
						} else {
							named = append(named, ii)
						}
					}
					if len(anon) > 0 {
						outGroups = append(outGroups, outGroup{GroupName: g, Imps: anon})
					}
					if len(named) > 0 {
						outGroups = append(outGroups, outGroup{GroupName: g, Imps: named})
					}
				} else {
					// One of blanked/dotted in order, other not: need mixed logic
					// For simplicity, if blanked in order but dotted not, then dotted mapped to underlying, so group may contain dotted and named etc.
					// We'll use same split as default: anon vs aliased (including blanked/dotted and named)
					// But for groups that are blanked or dotted themselves, we already handled.
					// For other groups, split anon vs named? Let's use anon vs named when blanked/dotted are separate? Actually we handled both separate case.
					// For mixed, use anon vs aliased
					var anon []impInfo
					var aliased []impInfo
					for _, ii := range impsInGroup {
						if ii.Alias == "" {
							anon = append(anon, ii)
						} else {
							aliased = append(aliased, ii)
						}
					}
					if len(anon) > 0 {
						outGroups = append(outGroups, outGroup{GroupName: g, Imps: anon})
					}
					if len(aliased) > 0 {
						outGroups = append(outGroups, outGroup{GroupName: g, Imps: aliased})
					}
				}
			} else {
				outGroups = append(outGroups, outGroup{GroupName: g, Imps: impsInGroup})
			}
		}

		var customImportBlock strings.Builder
		if len(outGroups) == 0 {
		} else if len(outGroups) == 1 && len(outGroups[0].Imps) == 1 && len(fileAst.Imports) <= 1 {
			ii := outGroups[0].Imps[0]
			commentStr := ""
			if ii.Orig != nil && ii.Orig.Comment != nil && len(ii.Orig.Comment.List) > 0 {
				var ctexts []string
				for _, c := range ii.Orig.Comment.List {
					ctexts = append(ctexts, c.Text)
				}
				commentStr = " " + strings.Join(ctexts, " ")
			}
			if ii.Alias != "" {
				customImportBlock.WriteString(fmt.Sprintf("import %s %q%s\n", ii.Alias, ii.Path, commentStr))
			} else {
				customImportBlock.WriteString(fmt.Sprintf("import %q%s\n", ii.Path, commentStr))
			}
		} else {
			customImportBlock.WriteString("import (\n")
			for gi, og := range outGroups {
				if gi > 0 {
					customImportBlock.WriteString("\n")
				}
				for _, ii := range og.Imps {
					commentStr := ""
					if ii.Orig != nil && ii.Orig.Comment != nil {
						var ctexts []string
						for _, c := range ii.Orig.Comment.List {
							ctexts = append(ctexts, c.Text)
						}
						if len(ctexts) > 0 {
							commentStr = " " + strings.Join(ctexts, " ")
						}
					}
					if ii.Alias != "" {
						customImportBlock.WriteString(fmt.Sprintf("\t%s %q%s\n", ii.Alias, ii.Path, commentStr))
					} else {
						customImportBlock.WriteString(fmt.Sprintf("\t%q%s\n", ii.Path, commentStr))
					}
				}
			}
			customImportBlock.WriteString(")\n")
		}

		origSrc := string(task.origContent)
		packageLine := ""
		lines := strings.Split(origSrc, "\n")
		foundPackage := false
		for _, line := range lines {
			if !foundPackage && strings.HasPrefix(strings.TrimSpace(line), "package ") {
				packageLine = line
				foundPackage = true
				break
			}
		}
		if packageLine == "" {
			packageLine = fmt.Sprintf("package %s", fileAst.Name.Name)
		}

		var importRanges [][2]token.Pos
		for _, decl := range fileAst.Decls {
			if gen, ok := decl.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
				importRanges = append(importRanges, [2]token.Pos{gen.Pos(), gen.End()})
			}
		}
		var filteredComments []*ast.CommentGroup
		for _, cg := range fileAst.Comments {
			inside := false
			for _, r := range importRanges {
				if cg.Pos() >= r[0] && cg.End() <= r[1] {
					inside = true
					break
				}
			}
			if !inside {
				filteredComments = append(filteredComments, cg)
			}
		}
		var newDeclsNoImport []ast.Decl
		for _, d := range fileAst.Decls {
			if gen, ok := d.(*ast.GenDecl); ok && gen.Tok == token.IMPORT {
				continue
			}
			newDeclsNoImport = append(newDeclsNoImport, d)
		}
		newFileNoImport := &ast.File{
			Package:  fileAst.Package,
			Name:     fileAst.Name,
			Decls:    newDeclsNoImport,
			Comments: filteredComments,
		}
		var bufNoImport bytes.Buffer
		cfg := printer.Config{Mode: printer.TabIndent | printer.UseSpaces, Tabwidth: 8}
		err = cfg.Fprint(&bufNoImport, fset, newFileNoImport)
		if err != nil {
			task.formattedContent = task.origContent
			task.changed = false
			continue
		}
		restFormattedFull := bufNoImport.String()
		restParts := strings.SplitN(restFormattedFull, "\n", 2)
		var restOnly string
		if len(restParts) == 2 {
			restOnly = restParts[1]
		} else {
			restOnly = ""
		}

		finalStr := packageLine + "\n"
		if customImportBlock.Len() > 0 {
			finalStr += "\n" + customImportBlock.String()
			if strings.TrimSpace(restOnly) != "" {
				finalStr += "\n" + strings.TrimLeft(restOnly, "\n")
			}
		} else {
			if strings.TrimSpace(restOnly) != "" {
				finalStr += "\n" + strings.TrimLeft(restOnly, "\n")
			}
		}
		if !strings.HasSuffix(finalStr, "\n") {
			finalStr += "\n"
		}
		if formatFlag {
			finalStr = addBlankLinesBetweenDecls(finalStr)
		}
		task.formattedContent = []byte(finalStr)
		if !bytes.Equal(task.origContent, task.formattedContent) {
			task.changed = true
			anyChangedForExit = true
		}
	}

	if filePath != "" {
		log.Printf("-file-path is deprecated. Put file name(s) as last argument to the command(Example: goimports-reviser -rm-unused -set-alias -format goimports-reviser/main.go)")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
	}
	if localStr != "" {
		log.Printf("-local is deprecated and will be removed soon. Use -company-prefixes instead.")
		log.Printf("All changes to file are applied, but command-line syntax should be fixed")
	}

	for _, task := range tasks {
		if task.skip || task.errorOccurred {
			continue
		}
		if outputMode == "file" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		} else if outputMode == "stdout" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					if task.changed {
						fmt.Println(task.absPath)
					} else {
						fmt.Print(string(task.formattedContent))
					}
				}
			} else {
				if task.isDotDot {
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				} else {
					fmt.Print(string(task.formattedContent))
				}
			}
		} else if outputMode == "write" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		}
	}

	if setExitStatus {
		if anyChangedForExit {
			os.Exit(1)
		}
	}
	if hasError {
		os.Exit(1)
	}
}
