	// For generated file handling with output modes, we have tasks with skip flag
	// We need to handle them for explicit vs dotdot
	for _, task := range tasks {
		if task.errorOccurred {
			continue
		}
		if task.skip {
			// Generated file without apply: skip for dotdot, handle for explicit
			if task.isDotDot {
