actions.command:
cd /workspace
# For explicit generated file handling, our current logic for skip is flawed.
# We handled skip for dotdot as continue (ignore), but for explicit we attempted to handle but our earlier code for explicit generated without apply gave empty stdout, not original.
# Need to fix explicit generated handling.

# From earlier analysis:
# For explicit generated without apply:
# - file (no list-diff): no stdout, file unchanged
# - file+list-diff: stdout filename, file unchanged
# - stdout (no list-diff): stdout original content
# - stdout+list-diff: stdout original content (not filename)
# - write (no list-diff): no stdout, file unchanged
# - write+list-diff: stdout filename, file unchanged

# So for explicit generated skip:
# - If outputMode file or write and listDiff false: do nothing (no stdout, no write)
# - If outputMode file or write and listDiff true: print absPath
# - If outputMode stdout: print origContent regardless of listDiff

# Let's implement that.

cat > main.go <<'GO'
package main

import (
	"bytes"
	"flag"
	"fmt"
	"go/ast"
	"go/parser"
	"go/printer"
	"go/token"
	"io/fs"
	"log"
	"os"
	"path/filepath"
	"sort"
	"strings"
)

const versionStr = "3.0.0-20260611193416-a37f51062178"
const builtWith = "go1.26.0"

func isGeneratedFile(content []byte) bool {
	s := string(content)
	lines := strings.Split(s, "\n")
	for _, line := range lines {
		trim := strings.TrimSpace(line)
		if trim == "" {
			continue
		}
		if strings.HasPrefix(trim, "//") {
			if strings.HasPrefix(trim, "// Code generated") {
				return true
			}
			return false
		}
		return false
	}
	return false
}

func isVersionDir(s string) bool {
	if len(s) < 2 {
		return false
	}
	if s[0] != 'v' {
		return false
	}
	for _, c := range s[1:] {
		if c < '0' || c > '9' {
			return false
		}
	}
	return true
}

func trimVersionSuffix(s string) string {
	idx := strings.LastIndex(s, ".")
	if idx == -1 {
		return s
	}
	suf := s[idx+1:]
	if isVersionDir(suf) {
		return s[:idx]
	}
	return s
}

func getPackageNameFromPath(path string) string {
	path = strings.TrimSuffix(path, "/")
	if path == "" {
		return ""
	}
	parts := strings.Split(path, "/")
	last := parts[len(parts)-1]
	if isVersionDir(last) {
		if len(parts) >= 2 {
			prev := parts[len(parts)-2]
			return trimVersionSuffix(prev)
		}
		return last
	}
	return trimVersionSuffix(last)
}

func getAliasForVersionedPath(path string) string {
	path = strings.TrimSuffix(path, "/")
	parts := strings.Split(path, "/")
	if len(parts) == 0 {
		return ""
	}
	last := parts[len(parts)-1]
	if isVersionDir(last) {
		if len(parts) >= 2 {
			prev := parts[len(parts)-2]
			alias := trimVersionSuffix(prev)
			if alias == "" {
				alias = prev
			}
			return alias
		}
		return ""
	}
	if strings.Contains(last, ".v") {
		idx := strings.LastIndex(last, ".")
		if idx != -1 {
			suf := last[idx+1:]
			if isVersionDir(suf) {
				return last[:idx]
			}
		}
	}
	return ""
}

func isStdPackage(path string) bool {
	return !strings.Contains(path, ".")
}

func isProjectImport(path, projectName string) bool {
	if projectName == "" {
		return false
	}
	if strings.HasSuffix(projectName, "/") {
		return false
	}
	if path == projectName {
		return true
	}
	if strings.HasPrefix(path, projectName+"/") {
		return true
	}
	return false
}

func isCompanyImport(path string, companyPrefixes []string) bool {
	if len(companyPrefixes) == 0 {
		return false
	}
	for _, cp := range companyPrefixes {
		if cp == "" {
			continue
		}
		if strings.HasPrefix(path, cp) {
			return true
		}
	}
	return false
}

func addBlankLinesBetweenDecls(src string) string {
	fset := token.NewFileSet()
	file, err := parser.ParseFile(fset, "tmp.go", src, parser.ParseComments)
	if err != nil {
		return src
	}
	var buf bytes.Buffer
	buf.WriteString(fmt.Sprintf("package %s\n", file.Name.Name))
	if len(file.Decls) > 0 {
		buf.WriteString("\n")
	}
	for i, decl := range file.Decls {
		if i > 0 {
			buf.WriteString("\n")
		}
		var b bytes.Buffer
		printer.Fprint(&b, fset, decl)
		buf.WriteString(b.String())
		buf.WriteString("\n")
	}
	return buf.String()
}

func main() {
	var (
		applyToGenerated   bool
		companyPrefixesStr string
		excludesStr        string
		filePath           string
		formatFlag         bool
		importsOrderStr    string
		listDiff           bool
		localStr           string
		outputStr          string
		projectName        string
		recursive          bool
		rmUnused           bool
		separateNamed      bool
		setAlias           bool
		setExitStatus      bool
		useCache           bool
		showVersion        bool
		showVersionOnly    bool
	)
	flag.BoolVar(&applyToGenerated, "apply-to-generated-files", false, "Apply imports sorting and formatting(if the option is set) to generated files. Generated file is a file with first comment which starts with comment '// Code generated'. Optional parameter.")
	flag.StringVar(&companyPrefixesStr, "company-prefixes", "", "Company package prefixes which will be placed after 3rd-party group by default(if defined). Values should be comma-separated. Optional parameters.")
	flag.StringVar(&excludesStr, "excludes", "", "Exclude files or dirs, example: '.git/,proto/*.go'.")
	flag.StringVar(&filePath, "file-path", "", "Deprecated. Put file name as an argument(last item) of command line.")
	flag.BoolVar(&formatFlag, "format", false, "Option will perform additional formatting. Optional parameter.")
	flag.StringVar(&importsOrderStr, "imports-order", "std,general,company,project", "Your imports groups can be sorted in your way. \nstd - std import group; \ngeneral - libs for general purpose; \ncompany - inter-org or your company libs(if you set '-company-prefixes'-option, then 4th group will be split separately. In other case, it will be the part of general purpose libs); \nproject - your local project dependencies;\nblanked - imports with \"_\" alias;\ndotted - imports with \".\" alias.\nOptional parameter.")
	flag.BoolVar(&listDiff, "list-diff", false, "Option will list files whose formatting differs from goimports-reviser. Optional parameter.")
	flag.StringVar(&localStr, "local", "", "Deprecated")
	flag.StringVar(&outputStr, "output", "file", "Can be \"file\", \"write\" or \"stdout\". Whether to write the formatted content back to the file or to stdout. When \"write\" together with \"-list-diff\" will list the file name and write back to the file. Optional parameter.")
	flag.StringVar(&projectName, "project-name", "", "Your project name(ex.: github.com/incu6us/goimports-reviser). Optional parameter.")
	flag.BoolVar(&recursive, "recursive", false, "Apply rules recursively if target is a directory. In case of ./... execution will be recursively applied by default. Optional parameter.")
	flag.BoolVar(&rmUnused, "rm-unused", false, "Remove unused imports. Optional parameter.")
	flag.BoolVar(&separateNamed, "separate-named", false, "Option will separate named imports from the rest of the imports, per group. Optional parameter.")
	flag.BoolVar(&setAlias, "set-alias", false, "Set alias for versioned package names, like 'github.com/go-pg/pg/v9'. In this case import will be set as 'pg \"github.com/go-pg/pg/v9\"'. Optional parameter.")
	flag.BoolVar(&setExitStatus, "set-exit-status", false, "set the exit status to 1 if a change is needed/made. Optional parameter.")
	flag.BoolVar(&useCache, "use-cache", false, "Use cache to improve performance. Optional parameter.")
	flag.BoolVar(&showVersion, "version", false, "Show version information")
	flag.BoolVar(&showVersionOnly, "version-only", false, "Show only the version string")

	flag.Usage = func() {
		fmt.Fprintf(os.Stderr, "Usage of %s:\n", os.Args[0])
		flag.PrintDefaults()
	}
	flag.Parse()

	if showVersion {
		fmt.Printf("version: %s\n", versionStr)
		fmt.Printf("built with: %s\n", builtWith)
		fmt.Printf("tag: %s\n", versionStr)
		fmt.Printf("commit: n/a\n")
		fmt.Printf("source: github.com/incu6us/goimports-reviser/v3\n")
		return
	}
	if showVersionOnly {
		fmt.Println(versionStr)
		return
	}

	orderGroups := []string{}
	if importsOrderStr != "" {
		for _, part := range strings.Split(importsOrderStr, ",") {
			t := strings.TrimSpace(part)
			if t == "" {
				continue
			}
			orderGroups = append(orderGroups, t)
		}
		if len(orderGroups) < 4 {
			flag.Usage()
			log.Fatalf("use default at least 4 parameters to sort groups of your imports: \"std,general,company,project\"")
		}
		allowed := map[string]bool{"std": true, "general": true, "company": true, "project": true, "blanked": true, "dotted": true}
		for _, g := range orderGroups {
			if !allowed[g] {
				flag.Usage()
				log.Fatalf("unknown order group type: \"%s\"", g)
			}
		}
	} else {
		orderGroups = []string{"std", "general", "company", "project"}
	}

	args := flag.Args()
	var paths []string
	if filePath != "" {
		paths = append(paths, filePath)
	}
	paths = append(paths, args...)

	if len(paths) == 0 {
		flag.Usage()
		log.Println("no file(s) or directory(ies) specified on input")
		return
	}

	log.Printf("Paths: %v\n", paths)

	var companyPrefixes []string
	if companyPrefixesStr != "" {
		for _, cp := range strings.Split(companyPrefixesStr, ",") {
			cp = strings.TrimSpace(cp)
			if cp != "" {
				companyPrefixes = append(companyPrefixes, cp)
			}
		}
	}

	var excludePatterns []string
	if excludesStr != "" {
		for _, ep := range strings.Split(excludesStr, ",") {
			ep = strings.TrimSpace(ep)
			if ep != "" {
				excludePatterns = append(excludePatterns, ep)
			}
		}
	}

	isExcluded := func(absPath string) bool {
		cwd, _ := os.Getwd()
		rel, err := filepath.Rel(cwd, absPath)
		if err != nil {
			rel = absPath
		}
		for _, pat := range excludePatterns {
			if strings.HasSuffix(pat, "/") {
				if strings.HasPrefix(rel, pat) || strings.HasPrefix(absPath, pat) || strings.Contains(rel, pat) || strings.Contains(absPath, pat) {
					return true
				}
				trimmed := strings.TrimSuffix(pat, "/")
				if strings.HasPrefix(rel, trimmed+"/") || rel == trimmed {
					return true
				}
				continue
			}
			if ok, _ := filepath.Match(pat, rel); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, absPath); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, filepath.ToSlash(rel)); ok {
				return true
			}
			if ok, _ := filepath.Match(pat, filepath.ToSlash(absPath)); ok {
				return true
			}
		}
		return false
	}

	outputMode := outputStr
	if outputMode != "file" && outputMode != "stdout" && outputMode != "write" {
		outputMode = "file"
	}

	type fileTask struct {
		absPath          string
		relArg           string
		isDotDot         bool
		origContent      []byte
		formattedContent []byte
		changed          bool
		skip             bool
		isGenerated      bool
		errorOccurred    bool
	}

	var tasks []fileTask

	for _, p := range paths {
		log.Printf("Processing %s\n", p)
		if strings.Contains(p, "...") {
			base := strings.Split(p, "...")[0]
			base = strings.TrimSpace(base)
			if base == "" {
				base = "."
			}
			base = strings.TrimSuffix(base, "/")
			if base == "" {
				base = "."
			}
			var baseAbs string
			if filepath.IsAbs(base) {
				baseAbs = base
			} else {
				cwd, _ := os.Getwd()
				baseAbs = filepath.Join(cwd, base)
			}
			filepath.WalkDir(baseAbs, func(wp string, d fs.DirEntry, err error) error {
				if err != nil {
					return nil
				}
				if d.IsDir() {
					if isExcluded(wp) {
						return filepath.SkipDir
					}
					return nil
				}
				if !strings.HasSuffix(wp, ".go") {
					return nil
				}
				if isExcluded(wp) {
					return nil
				}
				content, err := os.ReadFile(wp)
				if err != nil {
					return nil
				}
				isGen := isGeneratedFile(content)
				if isGen && !applyToGenerated {
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: true, skip: true, formattedContent: content})
					return nil
				}
				tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: true, origContent: content, isGenerated: isGen})
				return nil
			})
			continue
		}
		fi, err := os.Stat(p)
		if err != nil {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
			continue
		}
		if fi.IsDir() {
			var dirAbs string
			if filepath.IsAbs(p) {
				dirAbs = p
			} else {
				cwd, _ := os.Getwd()
				dirAbs = filepath.Join(cwd, p)
			}
			if recursive {
				filepath.WalkDir(dirAbs, func(wp string, d fs.DirEntry, err error) error {
					if err != nil {
						return nil
					}
					if d.IsDir() {
						if isExcluded(wp) {
							return filepath.SkipDir
						}
						return nil
					}
					if !strings.HasSuffix(wp, ".go") {
						return nil
					}
					if isExcluded(wp) {
						return nil
					}
					content, err := os.ReadFile(wp)
					if err != nil {
						return nil
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						return nil
					}
					tasks = append(tasks, fileTask{absPath: wp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
					return nil
				})
			} else {
				entries, err := os.ReadDir(dirAbs)
				if err != nil {
					continue
				}
				for _, e := range entries {
					if e.IsDir() {
						continue
					}
					if !strings.HasSuffix(e.Name(), ".go") {
						continue
					}
					fp := filepath.Join(dirAbs, e.Name())
					if isExcluded(fp) {
						continue
					}
					content, err := os.ReadFile(fp)
					if err != nil {
						continue
					}
					isGen := isGeneratedFile(content)
					if isGen && !applyToGenerated {
						tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
						continue
					}
					tasks = append(tasks, fileTask{absPath: fp, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
				}
			}
		} else {
			absP := p
			if !filepath.IsAbs(p) {
				cwd, _ := os.Getwd()
				absP = filepath.Join(cwd, p)
			}
			if isExcluded(absP) {
				continue
			}
			content, err := os.ReadFile(absP)
			if err != nil {
				continue
			}
			isGen := isGeneratedFile(content)
			if isGen && !applyToGenerated {
				tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: true, skip: true, formattedContent: content})
				continue
			}
			tasks = append(tasks, fileTask{absPath: absP, relArg: p, isDotDot: false, origContent: content, isGenerated: isGen})
		}
	}

	projectNameForFile := func(absPath string) (string, error) {
		if projectName != "" {
			return projectName, nil
		}
		dir := filepath.Dir(absPath)
		for {
			goModPath := filepath.Join(dir, "go.mod")
			if _, err := os.Stat(goModPath); err == nil {
				data, err := os.ReadFile(goModPath)
				if err != nil {
					return "", err
				}
				lines := strings.Split(string(data), "\n")
				for _, line := range lines {
					line = strings.TrimSpace(line)
					if strings.HasPrefix(line, "module ") {
						modName := strings.TrimSpace(strings.TrimPrefix(line, "module"))
						return modName, nil
					}
				}
				return "", fmt.Errorf("open go.mod: no such file or directory")
			}
			parent := filepath.Dir(dir)
			if parent == dir {
				break
			}
			dir = parent
		}
		return "", fmt.Errorf("open go.mod: no such file or directory")
	}

	anyChangedForExit := false
	hasError := false

	for i := range tasks {
		task := &tasks[i]
		if task.skip {
			task.formattedContent = task.origContent
			task.changed = false
			continue
		}
		projName, err := projectNameForFile(task.absPath)
		if err != nil {
			flag.Usage()
			log.Printf("Could not determine project name for path %s: %v\n", task.relArg, err)
			task.errorOccurred = true
			task.formattedContent = task.origContent
			hasError = true
			continue
		}

