					outGroups = append(outGroups, outGroup{GroupName: g, Imps: impsInGroup})
					continue
				}
				if !hasBlanked && !hasDotted {
					var anon []impInfo
					var aliased []impInfo
					for _, ii := range impsInGroup {
						if ii.Alias == "" {
							anon = append(anon, ii)
						} else {
