				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		} else if outputMode == "stdout" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					if task.changed {
						fmt.Println(task.absPath)
					} else {
						fmt.Print(string(task.formattedContent))
					}
				}
			} else {
				if task.isDotDot {
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				} else {
					fmt.Print(string(task.formattedContent))
				}
			}
		} else if outputMode == "write" {
			if listDiff {
				if task.isDotDot {
					if task.changed {
						fmt.Println(task.absPath)
					}
				} else {
					fmt.Println(task.absPath)
					os.WriteFile(task.absPath, task.formattedContent, 0644)
				}
			} else {
				os.WriteFile(task.absPath, task.formattedContent, 0644)
			}
		}
	}

	if setExitStatus {
		if anyChangedForExit {
			os.Exit(1)
		}
	}
	if hasError {
		os.Exit(1)
	}
}
