		buf.WriteString("\n")
	}
	for i, decl := range file.Decls {
		if i > 0 {
			buf.WriteString("\n")
		}
		var b bytes.Buffer
		printer.Fprint(&b, fset, decl)
		buf.WriteString(b.String())
		buf.WriteString("\n")
	}
	return buf.String()
}

func main() {
	var (
