fileAst, _ := parser.ParseFile(fset, "a.go", src, parser.ParseComments)
// Create specs without copying comment pos, but with comment that has same text but new pos?
var specs []ast.Spec
for _, imp := range fileAst.Imports {
	// Create comment with same text but at same position relative?
	comment := &ast.CommentGroup{
		List: []*ast.Comment{{Slash: imp.Comment.List[0].Slash, Text: imp.Comment.List[0].Text}},
	}
	spec := &ast.ImportSpec{
		Path: &ast.BasicLit{Kind: token.STRING, Value: imp.Path.Value},
		Comment: comment,
